-- Gate 3B: complete truthful operating contracts without activation or send capacity.
-- Generated contract payload is fingerprint-guarded against the exact Gate 3A drafts.

-- Gate 3B operating-contract validation and activation guard.
-- Draft contracts are reviewable but remain blocked from activation.

CREATE OR REPLACE FUNCTION private.gate3a_valid_owner_contract(
  p_contract JSONB,
  p_expected_crm_owner TEXT,
  p_expected_automation_owner TEXT
)
RETURNS BOOLEAN
LANGUAGE SQL
IMMUTABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  SELECT COALESCE((jsonb_typeof(p_contract) = 'object'
    AND COALESCE(private.gate3a_jsonb_nonblank_text(p_contract -> 'crmAuthority'), FALSE)
    AND COALESCE(private.gate3a_jsonb_nonblank_text(p_contract -> 'automationRole'), FALSE)
    AND COALESCE(private.gate3a_jsonb_nonblank_text(p_contract -> 'dispatchAuthority'), FALSE)
    AND private.gate3a_jsonb_text_array(p_contract -> 'handoffRules', TRUE)
    AND p_contract ->> 'crmAuthority' = p_expected_crm_owner
    AND p_contract ->> 'automationRole' = p_expected_automation_owner
    AND p_contract ->> 'dispatchAuthority' IN ('none_in_gate_3a', 'none_in_gate_3b')), FALSE);
$$;

REVOKE ALL ON FUNCTION private.gate3a_valid_owner_contract(JSONB, TEXT, TEXT)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.gate3a_valid_owner_contract(JSONB, TEXT, TEXT)
  TO service_role;

CREATE OR REPLACE FUNCTION private.gate3b_operating_contract_fingerprint(
  p_version public.operating_strategy_versions
)
RETURNS TEXT
LANGUAGE SQL
IMMUTABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  SELECT md5(jsonb_build_object(
    'version', p_version.version,
    'status', p_version.status,
    'execution_mode', p_version.execution_mode,
    'title', p_version.title,
    'destination_mode', p_version.destination_mode,
    'destination_path', p_version.destination_path,
    'cta_label', p_version.cta_label,
    'contract_json', p_version.contract_json,
    'lifecycle_contract_json', p_version.lifecycle_contract_json,
    'owner_contract_json', p_version.owner_contract_json,
    'outcome_contract_json', p_version.outcome_contract_json,
    'source_provenance_json', p_version.source_provenance_json,
    'crm_owner_key', p_version.crm_owner_key,
    'automation_owner_key', p_version.automation_owner_key,
    'external_send_cap', p_version.external_send_cap,
    'approved_by_user_id', p_version.approved_by_user_id,
    'approved_at', p_version.approved_at,
    'activated_at', p_version.activated_at,
    'retired_at', p_version.retired_at,
    'supersedes_id', p_version.supersedes_id
  )::TEXT);
$$;

REVOKE ALL ON FUNCTION private.gate3b_operating_contract_fingerprint(public.operating_strategy_versions)
  FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION private.gate3b_jsonb_object_array(
  p_value JSONB,
  p_require_nonempty BOOLEAN
)
RETURNS BOOLEAN
LANGUAGE plpgsql
IMMUTABLE
SECURITY INVOKER
SET search_path = ''
AS $$
BEGIN
  IF jsonb_typeof(p_value) IS DISTINCT FROM 'array' THEN
    RETURN FALSE;
  END IF;
  IF p_require_nonempty AND jsonb_array_length(p_value) = 0 THEN
    RETURN FALSE;
  END IF;
  RETURN NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_value) item
    WHERE jsonb_typeof(item) IS DISTINCT FROM 'object'
  );
END;
$$;

CREATE OR REPLACE FUNCTION private.gate3b_activation_ready(p_contract JSONB)
RETURNS BOOLEAN
LANGUAGE plpgsql
IMMUTABLE
SECURITY INVOKER
SET search_path = ''
AS $$
BEGIN
  IF jsonb_typeof(p_contract -> 'activationReadiness') IS DISTINCT FROM 'object' THEN
    RETURN FALSE;
  END IF;
  IF p_contract #>> '{activationReadiness,status}' IS DISTINCT FROM 'ready' THEN
    RETURN FALSE;
  END IF;
  IF NOT private.gate3a_jsonb_text_array(
    p_contract #> '{activationReadiness,readyElements}',
    TRUE
  ) THEN
    RETURN FALSE;
  END IF;
  IF jsonb_typeof(p_contract #> '{activationReadiness,blockers}') IS DISTINCT FROM 'array' THEN
    RETURN FALSE;
  END IF;
  RETURN jsonb_array_length(p_contract #> '{activationReadiness,blockers}') = 0;
END;
$$;

CREATE OR REPLACE FUNCTION private.gate3b_valid_review_contract(
  p_version public.operating_strategy_versions
)
RETURNS BOOLEAN
LANGUAGE SQL
IMMUTABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  SELECT COALESCE((p_version.version = 1
    AND p_version.status = 'draft'
    AND p_version.approved_by_user_id IS NULL
    AND p_version.approved_at IS NULL
    AND p_version.activated_at IS NULL
    AND p_version.retired_at IS NULL
    AND p_version.supersedes_id IS NULL
    AND p_version.external_send_cap = 0
    AND (
      (p_version.destination_mode = 'public_route' AND p_version.execution_mode = 'no_send')
      OR (p_version.destination_mode = 'internal_only' AND p_version.execution_mode = 'internal_only')
      OR (p_version.destination_mode = 'unresolved' AND p_version.execution_mode = 'inactive')
    )
    AND private.gate3a_valid_operating_contract(p_version.contract_json)
    AND private.gate3a_valid_lifecycle_contract(p_version.lifecycle_contract_json)
    AND private.gate3a_valid_owner_contract(
      p_version.owner_contract_json,
      p_version.crm_owner_key,
      p_version.automation_owner_key
    )
    AND private.gate3a_valid_outcome_contract(p_version.outcome_contract_json)
    AND private.gate3a_valid_source_provenance(p_version.source_provenance_json)
    AND COALESCE(private.gate3a_jsonb_nonblank_text(p_version.contract_json -> 'offer'), FALSE)
    AND private.gate3a_jsonb_text_array(p_version.contract_json -> 'prioritizationRules', TRUE)
    AND private.gate3a_jsonb_text_array(p_version.contract_json -> 'channelSelectionRules', TRUE)
    AND private.gate3a_jsonb_text_array(p_version.contract_json -> 'nurtureRules', TRUE)
    AND private.gate3a_jsonb_text_array(p_version.contract_json -> 'reactivationRules', TRUE)
    AND private.gate3b_jsonb_object_array(p_version.contract_json -> 'sourceDataRequirements', TRUE)
    AND private.gate3b_jsonb_object_array(p_version.contract_json -> 'cadenceSteps', TRUE)
    AND private.gate3b_jsonb_object_array(p_version.contract_json -> 'crossLaneRoutes', FALSE)
    AND private.gate3b_jsonb_object_array(p_version.contract_json -> 'integrationDependencies', TRUE)
    AND p_version.contract_json #>> '{activationReadiness,status}' = 'blocked'
    AND private.gate3a_jsonb_text_array(
      p_version.contract_json #> '{activationReadiness,readyElements}',
      TRUE
    )
    AND private.gate3a_jsonb_text_array(
      p_version.contract_json #> '{activationReadiness,blockers}',
      TRUE
    )
    AND p_version.contract_json #>> '{versionDecisionRule,requiredCompleteWindows}' = '2'
    AND p_version.contract_json #> '{versionDecisionRule,autonomousMaterialChange}' = 'false'::JSONB
    AND COALESCE(private.gate3a_jsonb_nonblank_text(p_version.lifecycle_contract_json -> 'recordAuthority'), FALSE)
    AND private.gate3a_jsonb_text_array(p_version.lifecycle_contract_json -> 'persistedStates', FALSE)
    AND private.gate3a_jsonb_text_array(p_version.lifecycle_contract_json -> 'persistedEvents', FALSE)
    AND private.gate3a_jsonb_text_array(p_version.lifecycle_contract_json -> 'targetOnlyStages', FALSE)
    AND jsonb_typeof(p_version.lifecycle_contract_json -> 'stateNotes') = 'object'
    AND COALESCE(private.gate3a_jsonb_nonblank_text(p_version.owner_contract_json -> 'recordOwner'), FALSE)
    AND COALESCE(private.gate3a_jsonb_nonblank_text(p_version.owner_contract_json -> 'humanOwner'), FALSE)
    AND p_version.owner_contract_json ->> 'dispatchAuthority' = 'none_in_gate_3b'
    AND COALESCE(private.gate3a_jsonb_nonblank_text(p_version.outcome_contract_json -> 'exposureUnit'), FALSE)
    AND COALESCE(private.gate3a_jsonb_nonblank_text(p_version.outcome_contract_json -> 'verifiedOutcomeRule'), FALSE)
    AND private.gate3a_jsonb_text_array(p_version.outcome_contract_json -> 'safeguards', TRUE)
    AND CASE
      WHEN jsonb_typeof(p_version.outcome_contract_json -> 'minimumPrimaryConversions') = 'number'
        AND (p_version.outcome_contract_json ->> 'minimumPrimaryConversions') ~ '^[1-9][0-9]*$'
        AND jsonb_typeof(p_version.outcome_contract_json -> 'minimumExposure') = 'number'
        AND (p_version.outcome_contract_json ->> 'minimumExposure') ~ '^[1-9][0-9]*$'
      THEN (p_version.outcome_contract_json ->> 'minimumExposure')::INTEGER > 1
        AND (p_version.outcome_contract_json ->> 'minimumPrimaryConversions')::INTEGER
          <= (p_version.outcome_contract_json ->> 'minimumExposure')::INTEGER
      ELSE FALSE
    END
    AND p_version.outcome_contract_json ->> 'requiredCompleteWindows' = '2'
    AND jsonb_typeof(p_version.outcome_contract_json -> 'targetOutcomeObservable') = 'boolean'
    AND jsonb_typeof(p_version.outcome_contract_json -> 'observableCurrentOutcome') = 'object'
    AND jsonb_typeof(p_version.outcome_contract_json #> '{observableCurrentOutcome,available}') = 'boolean'
    AND p_version.outcome_contract_json -> 'targetOutcomeObservable'
      = p_version.outcome_contract_json #> '{observableCurrentOutcome,available}'
    AND COALESCE(private.gate3a_jsonb_nonblank_text(
      p_version.outcome_contract_json #> '{observableCurrentOutcome,evidence}'
    ), FALSE)
    AND COALESCE(private.gate3a_jsonb_nonblank_text(
      p_version.outcome_contract_json #> '{observableCurrentOutcome,limitation}'
    ), FALSE)), FALSE);
$$;

REVOKE ALL ON FUNCTION private.gate3b_jsonb_object_array(JSONB, BOOLEAN)
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION private.gate3b_activation_ready(JSONB)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.gate3b_activation_ready(JSONB)
  TO service_role;
REVOKE ALL ON FUNCTION private.gate3b_valid_review_contract(public.operating_strategy_versions)
  FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.validate_operating_strategy_review(p_version_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  candidate public.operating_strategy_versions;
BEGIN
  SELECT version.* INTO candidate
  FROM public.operating_strategy_versions version
  WHERE version.id = p_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Operating strategy version not found.' USING ERRCODE = '23514';
  END IF;
  IF NOT COALESCE(private.gate3b_valid_review_contract(candidate), FALSE) THEN
    RAISE EXCEPTION 'The Gate 3B operating strategy review contract is incomplete or unsafe.'
      USING ERRCODE = '23514';
  END IF;
  RETURN TRUE;
END;
$$;

REVOKE ALL ON FUNCTION public.validate_operating_strategy_review(UUID)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.validate_operating_strategy_review(UUID)
  TO service_role;

CREATE OR REPLACE FUNCTION private.gate3b_guard_activation_readiness()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  entering_active BOOLEAN := FALSE;
BEGIN
  IF NEW.status = 'active' THEN
    IF TG_OP = 'INSERT' THEN
      entering_active := TRUE;
    ELSE
      entering_active := OLD.status IS DISTINCT FROM 'active';
    END IF;
  END IF;
  IF entering_active
    AND NOT COALESCE(private.gate3b_activation_ready(NEW.contract_json), FALSE) THEN
    RAISE EXCEPTION 'The operating contract still has unresolved activation blockers.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION private.gate3b_guard_activation_readiness()
  FROM PUBLIC, anon, authenticated, service_role;

DROP TRIGGER IF EXISTS operating_strategy_versions_gate3b_activation_readiness_guard
  ON public.operating_strategy_versions;
CREATE TRIGGER operating_strategy_versions_gate3b_activation_readiness_guard
BEFORE INSERT OR UPDATE OF status, contract_json
ON public.operating_strategy_versions
FOR EACH ROW EXECUTE FUNCTION private.gate3b_guard_activation_readiness();

CREATE OR REPLACE FUNCTION public.validate_operating_strategy_version(p_version_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  candidate public.operating_strategy_versions;
BEGIN
  SELECT version.* INTO candidate
  FROM public.operating_strategy_versions version
  WHERE version.id = p_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Operating strategy version not found.' USING ERRCODE = '23514';
  END IF;
  PERFORM private.gate3a_assert_operating_strategy_version(candidate);
  IF NOT COALESCE(private.gate3b_activation_ready(candidate.contract_json), FALSE) THEN
    RAISE EXCEPTION 'The operating contract still has unresolved activation blockers.'
      USING ERRCODE = '23514';
  END IF;
  RETURN TRUE;
END;
$$;

REVOKE ALL ON FUNCTION public.validate_operating_strategy_version(UUID)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.validate_operating_strategy_version(UUID)
  TO service_role;

-- Deterministic Gate 3B draft-contract update generated from TypeScript contracts.
-- This output is inert until it is separately reviewed, timestamped, and executed as a migration.
-- It does not activate a strategy, grant send capacity, or connect to a database.
DO $gate3b_guard$
DECLARE
  expected_strategy_keys CONSTANT TEXT[] := ARRAY['business_acquisition_network', 'business_formation_readiness', 'buyer_buy_box_activation', 'capital_readiness_intake', 'content_authority_intelligence', 'credit_education_support', 'customer_lifecycle_orchestration', 'dealvault_activation', 'investor_capital_relationships', 'lender_provider_criteria', 'next_move_free_roadmap', 'partner_referral_network', 'professional_participant_activation', 'property_opportunity_discovery', 'public_sector_opportunity_readiness', 'seller_options_intake', 'service_provider_network']::TEXT[];
BEGIN
  IF (
    SELECT count(*)
    FROM public.operating_strategies strategy
    JOIN public.operating_strategy_versions version
      ON version.operating_strategy_id = strategy.id
    WHERE strategy.strategy_key = ANY(expected_strategy_keys)
      AND version.version = 1
  ) <> 17 THEN
    RAISE EXCEPTION 'Gate 3B requires exactly 17 existing version-1 operating contracts';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.operating_strategies strategy
    JOIN public.operating_strategy_versions version
      ON version.operating_strategy_id = strategy.id
    WHERE strategy.strategy_key = ANY(expected_strategy_keys)
      AND version.version = 1
      AND (
        version.status <> 'draft'
        OR version.external_send_cap <> 0
        OR version.owner_contract_json ->> 'dispatchAuthority' <> 'none_in_gate_3a'
        OR version.outcome_contract_json ->> 'minimumExposure' <> '1'
        OR jsonb_array_length(version.source_provenance_json) <> 1
        OR NOT version.source_provenance_json @> '[{"source":"Gate 2 canonical strategy registry"}]'::JSONB
      )
  ) THEN
    RAISE EXCEPTION 'Gate 3B refuses to update a non-draft, send-capable, or non-Gate-3A version';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.operating_strategies strategy
    JOIN public.operating_strategy_versions version
      ON version.operating_strategy_id = strategy.id
    JOIN public.operating_strategy_version_events event
      ON event.version_id = version.id
    WHERE strategy.strategy_key = ANY(expected_strategy_keys)
      AND version.version = 1
      AND event.event_type IN ('activated', 'retired')
  ) THEN
    RAISE EXCEPTION 'Gate 3B refuses to rewrite previously active or retired history';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset($gate3b_prior_fingerprints$[{"strategy_key":"business_acquisition_network","expected_prior_fingerprint":"6936da8cad6b053dd46c84e4fa35ded5"},{"strategy_key":"business_formation_readiness","expected_prior_fingerprint":"8ee6205d21e7692fc2599f85cb769c1a"},{"strategy_key":"buyer_buy_box_activation","expected_prior_fingerprint":"547bbf6dd2092408a72002abe5ee2962"},{"strategy_key":"capital_readiness_intake","expected_prior_fingerprint":"4957eee1c3a14b890af9d6a8f89f1ed4"},{"strategy_key":"content_authority_intelligence","expected_prior_fingerprint":"f6a00c11fbbe4ec0bceac7ddf623e5d8"},{"strategy_key":"credit_education_support","expected_prior_fingerprint":"a5fbafef7c1a5d6479119fdced6ffdea"},{"strategy_key":"customer_lifecycle_orchestration","expected_prior_fingerprint":"77a0e59192c2ff424bd37b73c59ab20d"},{"strategy_key":"dealvault_activation","expected_prior_fingerprint":"fde1e02bf64adad6bc2080b2d7f110a3"},{"strategy_key":"investor_capital_relationships","expected_prior_fingerprint":"7b83c30995b085b4b2280a622f6a435c"},{"strategy_key":"lender_provider_criteria","expected_prior_fingerprint":"cd6f9483b30f1a673bb51d6f10e0593e"},{"strategy_key":"next_move_free_roadmap","expected_prior_fingerprint":"6d95539184d91f860f4198a894dc6244"},{"strategy_key":"partner_referral_network","expected_prior_fingerprint":"d4d077c8276354853e81ca9dd54078df"},{"strategy_key":"professional_participant_activation","expected_prior_fingerprint":"7e42d0758603fc63a841d9569c405cee"},{"strategy_key":"property_opportunity_discovery","expected_prior_fingerprint":"e748f764c9b428a3d41a426cc9fb5ede"},{"strategy_key":"public_sector_opportunity_readiness","expected_prior_fingerprint":"a6429114c850a326b50d68c07766daa2"},{"strategy_key":"seller_options_intake","expected_prior_fingerprint":"1cad4e5ea289def47ed697c61580f163"},{"strategy_key":"service_provider_network","expected_prior_fingerprint":"0ecea1d24aaffb454e55bba68e1955ed"}]$gate3b_prior_fingerprints$::JSONB) AS expected(
      strategy_key TEXT,
      expected_prior_fingerprint TEXT
    )
    JOIN public.operating_strategies strategy
      ON strategy.strategy_key = expected.strategy_key
    JOIN public.operating_strategy_versions strategy_version
      ON strategy_version.operating_strategy_id = strategy.id
      AND strategy_version.version = 1
    WHERE private.gate3b_operating_contract_fingerprint(strategy_version)
      <> expected.expected_prior_fingerprint
  ) THEN
    RAISE EXCEPTION 'Gate 3B refuses to overwrite a version-1 draft whose exact Gate 3A fingerprint changed';
  END IF;
END
$gate3b_guard$;

WITH gate3b_manifest AS (
  SELECT *
  FROM jsonb_to_recordset($gate3b_json$[{"activation_blockers":["Version 1 remains draft and has no founder-approved activation event.","External send capacity is zero and no live-send approval exists.","Gate 3C canonical consumer binding is not implemented.","No governed record currently proves a qualified confidential business-acquisition intake and bilateral acceptance of an operator-controlled introduction.","The confidential intake, opportunity authority, disclosure lifecycle, licensing and compensation decision, and approved matching destination do not exist."],"automation_owner_key":"operator_manual","contract_json":{"activationReadiness":{"blockers":["Canonical operating-strategy version binding is absent.","No approved confidential destination, intake, opportunity authority, access model, or disclosure lifecycle exists.","No governed record currently proves a qualified confidential business-acquisition intake and bilateral acceptance of an operator-controlled introduction.","Licensing, securities, business-broker, compensation, conflicts, privacy, and confidentiality decisions are unresolved."],"readyElements":["The canonical strategy identity and parent portfolio are registered.","Gate 2 defines the proposed future confidential review offer and human-first boundary.","Capital and DealVault have explicit future cross-lane purposes that do not substitute for acquisition matching."],"status":"blocked"},"cadenceSteps":[{"channels":["no_outreach","operator_task"],"condition":"The strategy remains draft, inactive, unresolved, and externally capped at zero.","purpose":"Record missing integration and governance prerequisites without sourcing or contacting acquisition participants.","timing":"current Gate 3B posture"},{"channels":["operator_task"],"condition":"A later approved destination and confidential opportunity service have persisted a complete intake under an active strategy version.","purpose":"Verify identity, authority, confidentiality, criteria, capacity, conflicts, legal boundaries, and permitted disclosure.","timing":"future immediate review after a complete confidential intake"},{"channels":["website_notification","resend_email","outlook_graph","manual_phone_task"],"condition":"A later active version authorizes the selected channel, the participant gave purpose-specific permission, suppression is clear, and an operator approved the exact request.","purpose":"Request the exact missing participant-owned fact without disclosing another party or implying a match.","timing":"future days 7 and 21 after an incomplete or review-blocked intake"}],"channelSelectionRules":["Current channel posture is no_outreach; an operator task may document missing prerequisites but may not contact a prospect.","A future secure website intake becomes eligible only after its route, confidentiality, privacy, access, and record contracts are approved.","Future email, Outlook, or phone tasks require an activated version, bilateral purpose-specific permission, disclosure-stage approval, suppression clearance, and operator ownership."],"complianceLimits":["Do not guarantee funding, approval, credit-score change, deletion, income, investment return, property availability, government award, deal outcome, or transaction timing.","Keep analysis, matching, marketing, provider sharing, public display, and outreach permissions separate and purpose-specific.","Recheck global suppression, DNC, withdrawal, complaint, hard bounce, identity conflict, and destination health immediately before any later dispatch.","No confidential business or participant fact may be disclosed outside the exact permissioned disclosure stage.","VestBlock must not represent valuation, buyer or seller availability, financing, suitability, LOI, diligence, close, or return beyond verified facts.","Licensing, securities, business-broker, compensation, conflict, and referral requirements must be resolved before activation and rechecked for each relevant introduction."],"crossLaneRoutes":[{"handoff":"Create a purpose-specific Capital case containing only permitted financing facts; /capital remains a financing route, not the acquisition-network destination.","requiresReceivingStrategyAcceptance":true,"to":"capital_readiness_intake","trigger":"A verified acquisition participant separately requests acquisition financing readiness."},{"handoff":"Offer a separate permissioned DealVault review without automatically sharing confidential acquisition records.","requiresReceivingStrategyAcceptance":true,"to":"dealvault_activation","trigger":"Both parties accept a controlled introduction and request governed diligence, proof, milestone, or agreement coordination."},{"handoff":"Offer the shared profile path only if the selected role is supported; profile activation is not acquisition qualification or match consent.","requiresReceivingStrategyAcceptance":true,"to":"professional_participant_activation","trigger":"A prospective participant needs a reusable approved-role identity profile before a future confidential intake."}],"disqualificationCriteria":["Missing authority, identity mismatch, fabricated capacity, confidentiality conflict, or permission withdrawal.","Unsupported valuation, guaranteed financing, guaranteed buyer or seller, undisclosed conflict or compensation, or a request to bypass disclosure controls.","Legal, securities, business-broker, licensing, or other regulatory uncertainty that lacks qualified human review."],"eligibilityCriteria":["Seller authority or buyer identity/entity, role, and capacity path are verified.","Confidentiality consent, permitted disclosure fields, geography, industry, size, timing, structure, conflicts, and separate matching/outreach permissions are complete.","Any valuation, securities, business-broker, licensing, financing, compensation, and conflict boundary has an explicit operator disposition."],"failureConditions":["Missing confidential intake or destination","Identity or authority dispute","Confidentiality or disclosure conflict","Unsupported valuation or financing claim","Unverified capacity","Licensing, securities, compensation, or conflict uncertainty","Single-party or unreviewed introduction"],"followupCadence":["No current intake, nurture, matching, or outreach cadence is active.","A future complete confidential intake receives human-first review before any party is contacted or any information is disclosed.","Proposed follow-up is limited to consented days 7 and 21 for exact missing intake or review actions after activation."],"handoffRules":["A future acquisition record owns confidentiality, permitted disclosure, matching, and bilateral response; a Capital or Next Move record cannot substitute for it.","An operator must approve the exact disclosure package and match before either party is invited to accept an introduction.","Both parties must independently accept the same controlled introduction before any downstream LOI, diligence, Capital, or DealVault route."],"humanApprovalPoints":["Confidential destination and intake design","Identity, authority, capacity, and conflict review","Valuation, securities, business-broker, licensing, financing, and compensation boundaries","Every disclosure-stage change","Every match and bilateral introduction","LOI, diligence, closing, and verified-outcome representation"],"integrationDependencies":[{"evidence":"Application consumers do not yet persist or resolve canonical operating-strategy version IDs.","integration":"canonical strategy-version binding","requiredBeforeActivation":true,"status":"gate_3c"},{"evidence":"No approved secure destination captures the governed seller/buyer intake, confidentiality, disclosure, criteria, capacity, conflict, and permission contract.","integration":"Confidential business-acquisition destination and intake","requiredBeforeActivation":true,"status":"missing"},{"evidence":"No canonical confidential opportunity model owns business facts, participant roles, permitted fields, evidence, status, 