y language."],"complianceLimits":["Do not guarantee funding, approval, credit-score change, deletion, income, investment return, property availability, government award, deal outcome, or transaction timing.","Keep analysis, matching, marketing, provider sharing, public display, and outreach permissions separate and purpose-specific.","Recheck global suppression, DNC, withdrawal, complaint, hard bounce, identity conflict, and destination health immediately before any later dispatch.","Matching permission is not marketing permission, and a match is not a representation that a property is available."],"crossLaneRoutes":[{"handoff":"Return ownership to the shared pre-active profile journey.","requiresReceivingStrategyAcceptance":true,"to":"professional_participant_activation","trigger":"The prospective buyer has not completed active profile verification."},{"handoff":"Provide blinded demand criteria without authorizing seller contact.","requiresReceivingStrategyAcceptance":true,"to":"property_opportunity_discovery","trigger":"Current buyer demand justifies an internal source review."},{"handoff":"Create a separately consented Capital case.","requiresReceivingStrategyAcceptance":true,"to":"capital_readiness_intake","trigger":"A buyer requests acquisition financing readiness."},{"handoff":"Request DealVault activation after access approval.","requiresReceivingStrategyAcceptance":true,"to":"dealvault_activation","trigger":"An accepted reviewed match needs controlled evidence continuity."}],"disqualificationCriteria":["Inactive, stale, disputed, or unverified profile.","Missing matching permission or proof path.","A request for guaranteed inventory, returns, pricing, or transaction outcome."],"eligibilityCriteria":["participant_profiles status is active after professional participant activation","Buyer role and identity are verified.","Markets, asset types, economics, capacity/proof state, no-go criteria, matching permission, and communication preference are current."],"failureConditions":["Stale capacity","Repeated irrelevant match feedback","Missing response persistence","Withdrawn matching permission","Opportunity evidence conflict"],"followupCadence":["Post-activation criteria refresh every 30 days.","One notification per operator-approved relevant match.","No generic buyer blast or pre-activation reminder ownership."],"handoffRules":["Professional participant activation exclusively owns draft through active.","Buyer strategy begins only after the active handoff and owns criteria refresh and reviewed matches."],"humanApprovalPoints":["Initial opportunity share","Capacity representation","Investment-return or availability language","Property disclosure","Cross-party introduction"],"integrationDependencies":[{"evidence":"Application consumers do not yet persist or resolve canonical operating-strategy version IDs.","integration":"canonical strategy-version binding","requiredBeforeActivation":true,"status":"gate_3c"},{"evidence":"participant_profiles and events persist identity, role, permissions, and active status.","integration":"Participant profile service","requiredBeforeActivation":true,"status":"available"},{"evidence":"Current consumer truth does not provide a complete operator-reviewed match and participant-acceptance response authority.","integration":"Buyer match response lifecycle","requiredBeforeActivation":true,"status":"missing"},{"evidence":"Legacy buyers and buy boxes exist separately from participant profiles.","integration":"Legacy buyer bridge","requiredBeforeActivation":true,"status":"partial"}],"learningInputs":["criteria fit","pass reason","source","asset type","timing","price or structure gap","match quality","transaction stage"],"nurtureRules":["Nurture only around criteria freshness and explicit buyer interests.","Do not send generic inventory or repeat opportunities the buyer has passed."],"objective":"Maintain a verified, current buyer buy box and route only operator-reviewed, relevant property opportunities.","offer":"A free buyer profile, 30-day criteria refresh, and controlled match-review path.","primaryChannels":["website_notification","operator_task"],"prioritizationRules":["Prioritize exact current buy-box fit and verified capacity.","Prefer buyers who provide timely pass reasons and keep criteria current.","Do not rank by protected attributes or promised return."],"problem":"Buyer demand is not actionable when markets, property types, economics, capacity, no-go criteria, or permissions are incomplete or stale.","reactivationRules":["A dormant buyer reactivates only after current criteria, capacity, and matching permission are reconfirmed.","A passed opportunity does not reactivate without a materially changed verified fact."],"secondaryChannels":["resend_email","outlook_graph","no_outreach"],"sourceData":["participant_profiles","participant_profile_events","participant_matches","legacy buyers and buy boxes pending bridge"],"sourceDataRequirements":[{"authority":"Participant profile service","freshnessRule":"Refresh buyer criteria and capacity at least every 30 days before a new match.","requiredEvidence":["buyer role","active status","operator verification","matching permission","criteria","verification timestamp"],"source":"participant_profiles and participant_profile_events"},{"authority":"CRM match record plus operator-reviewed opportunity facts","freshnessRule":"Recheck property facts, availability boundary, and buyer criteria immediately before notification.","requiredEvidence":["profile ID","opportunity ID","fit factors","operator decision","response"],"source":"participant_matches and opportunity evidence"}],"stopRules":["Stop on opt-out, complaint, hard bounce, DNC, withdrawal, or permission loss.","Stop on a reply that needs human handling, a verified conversion, successful handoff, disqualification, or identity conflict.","Stop on stale evidence, an invalid destination, a missing strategy or message version, duplicate ownership, capacity failure, or a kill switch.","Pause the buyer role when criteria or capacity misses the 30-day refresh SLA."],"targetParticipant":"Active local, institutional, specialty, landlord, builder, and acquisition buyers with current criteria and capacity.","valueExchange":"The buyer maintains private criteria and matching permission in exchange for fewer, better operator-reviewed opportunities.","versionDecisionRule":{"autonomousMaterialChange":false,"promote":"Promote after two 45-day windows each include 20 operator-reviewed buyer matches and five verified acceptances without relevance or complaint regression.","requiredCompleteWindows":2,"retire":"Retire a segment or match rule after material misrepresentation or two complete windows without accepted matches.","revise":"Revise criteria, fit scoring, or notification timing when pass reasons identify a correctable mismatch."}},"crm_owner_key":"vestblock_crm","cta_label":"Create your free buyer profile","destination_mode":"public_route","destination_path":"/workspace/profiles/new?role=buyer","execution_mode":"no_send","expected_current_version":1,"expected_prior_fingerprint":"547bbf6dd2092408a72002abe5ee2962","external_activation":"blocked","external_send_cap":0,"lifecycle_contract_json":{"cadence":["Role strategy starts only after active.","Criteria refresh every 30 days.","Match notification only after operator review."],"initialState":"active","persistedEvents":["participant profile activation/verification event","profile pause/withdraw/archive event","partial participant match records"],"persistedStates":["active","paused","withdrawn","archived"],"recordAuthority":"participant_profiles and participant_profile_events own active/paused/withdrawn/archived profile truth; a complete buyer match-response authority is not yet present.","stateNotes":{"active":"active is persisted by participant_profiles/events and the incomplete participant_matches model.","archived":"archived is persisted by participant_profiles/events and the incomplete p