ilable":false,"evidence":"Profiles and partial match rows exist, but the consumer audit found no complete persisted response states proving buyer acceptance.","limitation":"Gate 3C must add canonical version and accepted-response binding before this conversion is measurable."},"primaryConversionEvent":"An operator-reviewed buyer match is explicitly accepted by the active buyer for review.","requiredCompleteWindows":2,"safeguards":["Require two complete learning windows before recommending promotion.","Do not declare a winner from opens, clicks, or other vanity engagement alone.","A complaint, compliance failure, identity conflict, duplicate dispatch, or suppression breach blocks promotion.","Material audience, offer, cadence, claim, destination, or channel changes remain human-reviewed proposals.","Do not count an active profile, computed match, notification, open, or click as participant acceptance."],"stopConditions":["irrelevant-match regression","stale criteria or capacity","permission withdrawal","unsupported opportunity claim","duplicate notification"],"targetOutcomeObservable":false,"verifiedOutcomeRule":"Count once when the operator-approved match record and the active buyer response record share an idempotent match ID and the response is accepted."},"owner_contract_json":{"automationRole":"vestblock_application","crmAuthority":"vestblock_crm","dispatchAuthority":"none_in_gate_3b","handoffRules":["Accept exactly one idempotent active-profile handoff.","Relinquish ownership to the transaction or DealVault strategy only after explicit acceptance."],"humanOwner":"A VestBlock operator owns opportunity review and introductions.","recordOwner":"Participant profile service owns profile truth; the canonical CRM must own post-active buyer match responses."},"required_current_status":"draft","source_provenance_json":[{"kind":"gate_3a_registry_seed","observedAt":"2026-08-15","source":"Gate 3A canonical governed registry"},{"kind":"founder_approved_architecture","observ