":["Do not guarantee funding, approval, credit-score change, deletion, income, investment return, property availability, government award, deal outcome, or transaction timing.","Keep analysis, matching, marketing, provider sharing, public display, and outreach permissions separate and purpose-specific.","Recheck global suppression, DNC, withdrawal, complaint, hard bounce, identity conflict, and destination health immediately before any later dispatch.","VestBlock does not represent a provider and must state that approval and terms are not guaranteed."],"crossLaneRoutes":[{"handoff":"Create a permissioned readiness handoff with the blocking gaps.","requiresReceivingStrategyAcceptance":true,"to":"business_formation_readiness","trigger":"Foundational entity, banking, or recordkeeping gaps prevent responsible capital review."},{"handoff":"Submit an operator-reviewed match request; never auto-submit the case.","requiresReceivingStrategyAcceptance":true,"to":"lender_provider_criteria","trigger":"The case is ready for provider review and provider-sharing permission is present."},{"handoff":"Offer an access-controlled DealVault review after the transaction owner accepts.","requiresReceivingStrategyAcceptance":true,"to":"dealvault_activation","trigger":"A qualified transaction needs controlled evidence and milestone continuity."}],"disqualificationCriteria":["Fabricated or materially conflicting facts, prohibited purpose, or unresolved identity conflict.","A request for guaranteed approval, terms, funding, or an unsupported underwriting conclusion.","Missing analysis consent or insufficient information to form a readiness case."],"eligibilityCriteria":["Identity and business, property, or project context are verified.","Use, amount, timing, present capacity, and material financial facts are supplied by the participant.","Analysis consent is recorded; provider-sharing and marketing permissions remain separate."],"failureConditions":["Stale provider criteria","Materially inconsistent customer facts","Unresolved consent boundary","Document-access failure","No responsible record owner"],"followupCadence":["Immediate submission acknowledgement.","One-business-day operator review target.","Permitted missing-item reminders at days 3, 7, and 14, then stop."],"handoffRules":["Capital owns readiness through ready-for-provider-review.","A receiving provider strategy must accept a permissioned handoff before any introduction."],"humanApprovalPoints":["Provider sharing","Underwriting-like or eligibility language","Provider introduction","Referral compensation","Material strategy activation"],"integrationDependencies":[{"evidence":"Application consumers do not yet persist or resolve canonical operating-strategy version IDs.","integration":"canonical strategy-version binding","requiredBeforeActivation":true,"status":"gate_3c"},{"evidence":"capital_cases and capital_case_events persist the current case lifecycle.","integration":"Capital case service","requiredBeforeActivation":true,"status":"available"},{"evidence":"Provider criteria foundations exist, but complete provider matching and provider-confirmed value attribution do not.","integration":"Provider matching and outcome capture","requiredBeforeActivation":true,"status":"partial"}],"learningInputs":["capital path","need type","readiness gaps","completion friction","provider-fit decision","stage time","verified provider response"],"nurtureRules":["Nurture is limited to the participant-selected capital purpose and documented readiness gaps.","After three unanswered permitted reminders, close the reminder sequence and leave the case available for customer-initiated return."],"objective":"Turn a defined capital need into a complete, reviewable readiness case without representing a lender or promising approval.","offer":"A private capital-readiness intake, document-gap analysis, readiness plan, and operator-reviewed provider-review path.","primaryChannels":["website_notification","operator_task"],"prioritizationRules":["Prioritize submitted cases with defined timing and complete identity before incomplete drafts.","Prioritize needs-information cases when one documented gap blocks readiness review.","Never prioritize by protected status or by a claimed likelihood of approval."],"problem":"Capital requests often reach providers before purpose, timing, records, constraints, and document gaps are organized.","reactivationRules":["Reactivate only after the participant updates a material fact, document, timing, or provider-sharing permission.","Recheck provider criteria freshness and suppression before reopening provider review."],"secondaryChannels":["resend_email","outlook_graph","no_outreach"],"sourceData":["capital_cases","capital_case_events","customer-submitted financial and business records","operator-reviewed provider criteria"],"sourceDataRequirements":[{"authority":"VestBlock Capital case service and append-only case events","freshnessRule":"Reconfirm material facts and provider criteria before provider review; do not infer freshness from case age alone.","requiredEvidence":["case type","purpose","amount or bounded need","timing","consents","document state","status event"],"source":"capital_cases and capital_case_events"}],"stopRules":["Stop on opt-out, complaint, hard bounce, DNC, withdrawal, or permission loss.","Stop on a reply that needs human handling, a verified conversion, successful handoff, disqualification, or identity conflict.","Stop on stale evidence, an invalid destination, a missing strategy or message version, duplicate ownership, capacity failure, or a kill switch.","Pause a provider path when rejection evidence shows systemic criteria mismatch."],"targetParticipant":"Businesses, property operators, acquisition buyers, grant seekers, and sponsors with a defined capital need.","valueExchange":"The participant provides accurate facts, documents, and purpose-specific permissions in exchange for a structured readiness review and bounded next steps.","versionDecisionRule":{"autonomousMaterialChange":false,"promote":"Promote only when readiness acceptance improves across two complete 30-day windows with at least 20 submitted cases and five verified readiness conversions per window, with no guardrail regression.","requiredCompleteWindows":2,"retire":"Retire a provider path after material compliance failure or two complete reviewed windows with no qualified readiness progress.","revise":"Revise a specific intake path when repeated, attributable document or criteria friction is correctable."}},"crm_owner_key":"vestblock_crm","cta_label":"Start your capital readiness review","destination_mode":"public_route","destination_path":"/capital","execution_mode":"no_send","expected_current_version":1,"expected_prior_fingerprint":"4957eee1c3a14b890af9d6a8f89f1ed4","external_activation":"blocked","external_send_cap":0,"lifecycle_contract_json":{"cadence":["Immediate submission acknowledgement.","One-business-day operator review target.","Permitted missing-item reminders at days 3, 7, and 14, then stop."],"initialState":"draft","persistedEvents":["capital_case_events.event_type","capital_case_events.from_status","capital_case_events.to_status"],"persistedStates":["draft","submitted","needs_information","under_review","readiness_plan","ready_for_provider_review","provider_review","approved","declined","withdrawn","closed"],"recordAuthority":"capital_cases is the current state authority; capital_case_events is the append-only transition authority.","stateNotes":{"approved":"approved is persisted by capital_cases.status, with transitions recorded in capital_case_events.","closed":"closed is persisted by capital_cases.status, with transitions recorded in capital_case_events.","declined":"declined is persisted by capital_cases.status, with transitions recorded in capital_case_events.","draft":"draft is persisted by capital_cases.status, with transitions recorded in capital_case_events.","needs_information":"needs_information is