or_queue_failed","from":"uploaded","persistence":"current","to":"failed"},{"event":"upload_requires_human_review","from":"uploaded","persistence":"current","to":"needs_review"},{"event":"text_extraction_completed","from":"extracting_text","persistence":"current","to":"text_extracted"},{"event":"text_extraction_failed","from":"extracting_text","persistence":"current","to":"failed"},{"event":"extraction_ambiguous","from":"extracting_text","persistence":"current","to":"needs_review"},{"event":"analysis_started","from":"text_extracted","persistence":"current","to":"analyzing"},{"event":"analysis_start_failed","from":"text_extracted","persistence":"current","to":"failed"},{"event":"text_requires_review","from":"text_extracted","persistence":"current","to":"needs_review"},{"event":"analysis_completed","from":"analyzing","persistence":"current","to":"completed"},{"event":"analysis_failed","from":"analyzing","persistence":"current","to":"failed"},{"event":"analysis_requires_review","from":"analyzing","persistence":"current","to":"needs_review"},{"event":"customer_opens_completed_analysis","from":"completed","persistence":"target_only","to":"customer_review"},{"event":"customer_saves_bounded_plan","from":"customer_review","persistence":"target_only","to":"action_plan_saved"},{"event":"professional_review_recommended","from":"customer_review","persistence":"target_only","to":"referred"},{"event":"customer_pauses","from":"customer_review","persistence":"target_only","to":"paused"},{"event":"customer_starts_action","from":"action_plan_saved","persistence":"target_only","to":"action_in_progress"},{"event":"customer_completes_plan","from":"action_plan_saved","persistence":"target_only","to":"education_completed"},{"event":"customer_pauses","from":"action_plan_saved","persistence":"target_only","to":"paused"},{"event":"checkpoint_due_or_reported","from":"action_in_progress","persistence":"target_only","to":"checkpoint"},{"event":"customer_confirms_completion","from":"checkpoint","persistence":"target_only","to":"education_completed"},{"event":"qualified_professional_review_needed","from":"checkpoint","persistence":"target_only","to":"referred"},{"event":"customer_pauses","from":"checkpoint","persistence":"target_only","to":"paused"}]},"outcome_contract_json":{"attributionDimensions":["portfolio","operating strategy version","credit report","analysis version","action plan","operator review","customer event"],"businessValue":"More informed customers and cleaner readiness paths without prohibited credit-repair claims.","exposureUnit":"analysis_ready_credit_reports","leadingIndicators":["secure upload completion","analysis-ready reports","needs-review rate","customer analysis review","plan-save attempt"],"learningInputs":["strategy version","workflow status","failure/review reason","analysis version","selected action","save event","checkpoint","feedback"],"learningWindowDays":60,"minimumExposure":25,"minimumPrimaryConversions":10,"observableCurrentOutcome":{"available":false,"evidence":"credit_reports proves processing through completed, but no customer-saved action-plan event is authoritative.","limitation":"The target conversion requires Gate 3C action-plan persistence and canonical version binding."},"primaryConversionEvent":"An analysis-ready authorized credit report produces a bounded action plan that the customer explicitly saves.","requiredCompleteWindows":2,"safeguards":["Require two complete learning windows before recommending promotion.","Do not declare a winner from opens, clicks, or other vanity engagement alone.","A complaint, compliance failure, identity conflict, duplicate dispatch, or suppression breach blocks promotion.","Material audience, offer, cadence, claim, destination, or channel changes remain human-reviewed proposals.","Do not treat upload, extraction, completed analysis, generated letters, email delivery, or score movement as a saved educational plan."],"stopConditions":["privacy or authorization failure","unsupported credit claim","high extraction/analysis failure","needs-review regression","deletion request"],"targetOutcomeObservable":false,"verifiedOutcomeRule":"Count once when an authorized completed credit_reports record and a customer-authenticated action_plan_saved event share the report ID and strategy version."},"owner_contract_json":{"automationRole":"vestblock_application","crmAuthority":"vestblock_crm","dispatchAuthority":"none_in_gate_3b","handoffRules":["Share only minimum permissioned readiness facts.","A receiving strategy accepts ownership and may not infer credit eligibility or outcome."],"humanOwner":"A VestBlock operator owns needs-review and regulated/legal edge cases.","recordOwner":"Credit workflow owns processing state; CRM must own future customer education/action events."},"required_current_status":"draft","source_provenance_json":[{"kind":"gate_3a_registry_seed","observedAt":"2026-08-15","source":"Gate 3A canonical governed registry"},{"kind":"founder_approved_architecture","observedAt":"2026-08-15","source":"Gate 2 canonical strategy registry"},{"kind":"repository_consumer_audit","observedAt":"2026-08-15","source":"credit_reports and creditRepairWorkflow consumer audit"}],"strategy_key":"credit_education_support"},{"activation_blockers":["Version 1 remains draft and has no founder-approved activation event.","External send capacity is zero and no live-send approval exists.","Gate 3C canonical consumer binding is not implemented.","No canonical record currently proves an eligible idempotent lifecycle proposal and explicit receiving-strategy acceptance.","The existing direct-reminder lifecycle monitor is legacy, unbound to this contract, and must not be treated as an approved sender."],"automation_owner_key":"vestblock_application","contract_json":{"activationReadiness":{"blockers":["Canonical operating-strategy version binding is absent.","No canonical record currently proves an eligible idempotent lifecycle proposal and explicit receiving-strategy acceptance.","Suppression, contact history, owner capacity, destination snapshots, and proposal expiry are not one enforced decision.","The legacy direct-reminder lifecycle monitor must be cut off from sender authority before activation."],"readyElements":["The approved architecture defines a strict internal-only control-plane boundary.","Several source records, task surfaces, reply-memory signals, and suppression fragments exist.","The contract requires receiving-strategy ownership before any communication."],"status":"blocked"},"cadenceSteps":[{"channels":["no_outreach"],"condition":"The source event is new, attributable, current, and not already represented by an open or completed idempotency key.","purpose":"Evaluate eligibility, ownership, contact history, suppression, destination, and capacity without external contact.","timing":"on a new authoritative lifecycle event or due freshness boundary"},{"channels":["operator_task"],"condition":"The active receiving strategy version, destination, CTA, owner, purpose, permission context, suppression result, and capacity are resolved and snapshotted.","purpose":"Create one internal proposal for the exact receiving strategy and accountable owner.","timing":"after all eligibility and safety checks pass"},{"channels":["operator_task","no_outreach"],"condition":"The receiving strategy has not accepted before the source evidence, destination, strategy version, or capacity snapshot expires.","purpose":"Close, suppress, or require fresh evaluation without sending a reminder.","timing":"at proposal evidence or owner-capacity expiry"}],"channelSelectionRules":["This controller may create an internal operator or receiving-strategy task proposal only.","It may not select an external channel, write message copy, call n8n, call a channel adapter, publish a CTA, or use a generic fallback destination.","After explicit acceptance, the receiving strategy independently rechecks eligibility, permission, suppression, destination, cadence, and capacity before any communication."],"complianceLimits":["Do not guarantee funding, approval, credit-score change, deletion, income, investment return, property availability, government award, deal outcome, or transaction timing.","Keep analysis, matching, marketing, provider sharing, public display, and outreach permissions separate and purpose-specific.","Recheck global suppression, DNC, withdrawal, complaint, hard bounce, identity conflict, and destination health immediately before any later dispatch.","Transactional permission may not be repurposed as marketing permission.","The controller cannot send, publish, call n8n, call a channel adapter, or use a generic homepage fallback.","A receiving strategy acceptance transfers only the proposed purpose and minimum approved context, never broad contact authority."],"crossLaneRoutes":[{"handoff":"Propose the exact /next-move route and require Next Move to accept before it owns any communication.","requiresReceivingStrategyAcceptance":true,"to":"next_move_free_roadmap","trigger":"A registered participant requests a fresh broad sequencing path and no more specific owner applies."},{"handoff":"Propose profile completion or review to the activation owner without preserving controller dispatch ownership.","requiresReceivingStrategyAcceptance":true,"to":"professional_participant_activation","trigger":"A participant started but did not complete a role profile or must resolve verification."},{"handoff":"Propose the exact Capital action with purpose-specific context; Capital must independently accept and qualify it.","requiresReceivingStrategyAcceptance":true,"to":"capital_readiness_intake","trigger":"A customer has a current separately requested capital-preparation action."},{"handoff":"Propose the case-owned /sell action only if Seller accepts current ownership and the case is not complete or suppressed.","requiresReceivingStrategyAcceptance":true,"to":"seller_options_intake","trigger":"A seller case has a current customer-requested unfinished next step."}],"disqualificationCriteria":["Anonymous or unowned record, ambiguous identity, stale evidence, unresolved duplicate, or missing receiving strategy and destination.","Suppression, DNC, opt-out, complaint, hard bounce, permission loss, completed action, exhausted path cap, or a prior response requiring human handling.","A generic homepage fallback, transactional-to-marketing purpose change, direct n8n invocation, or direct channel-adapter call."],"eligibilityCriteria":["A registered customer, profile, case, questionnaire, or record has a current authoritative incomplete, stale, or newly eligible signal.","The exact receiving strategy, active version, destination, CTA, owner, purpose, channel permission, contact history, suppression result, and capacity can be resolved.","No open proposal, active owner, completed action, complaint, withdrawal, identity conflict, or path-specific cap already blocks the action."],"failureConditions":["Duplicate proposal","Direct send or n8n invocation","Missing or inactive receiving strategy version","Broken or generic destination","Stale source evidence","Suppression or permission failure","Unresolved owner conflict","Receiving strategy cannot accept capacity"],"followupCadence":["Evaluate a lifecycle signal once when a new authoritative event or scheduled freshness boundary occurs.","Create at most one open idempotent proposal for the same participant, source event, purpose, and receiving strategy.","Expire or close an unaccepted proposal at its evidence or owner-capacity SLA; do not create a reminder from this controller."],"handoffRules":["Create one proposal keyed by participant, source event, purpose, receiving strategy, and current source version.","Snapshot the receiving strategy version, exact destination, CTA, owner, evidence, permissions, suppression result, and expiry without generating message copy.","Only explicit receiving-strategy acceptance transfers ownership; rejection, expiry, or invalidation closes the proposal with no external action.","Customer completion or route acceptance remains the receiving strategy's downstream business outcome, not an event this controller may fabricate."],"humanApprovalPoints":["Cross-lane financial, credit, investment, public-sector, or business-acquisition proposal","Long-dormant reactivation","Purpose or destination change","Identity, ownership, duplicate, or conflicting lifecycle state","Any response requiring interpretation","Receiving-strategy rejection or capacity conflict"],"integrationDependencies":[{"evidence":"Application consumers do not yet persist or resolve canonical operating-strategy version IDs.","integration":"canonical strategy-version binding","requiredBeforeActivation":true,"status":"gate_3c"},{"evidence":"Profiles, cases, questionnaires, workspace tasks, reply memory, and other records exist, but they do not share one canonical source-event and ownership contract.","integration":"Authoritative lifecycle source records","requiredBeforeActivation":true,"status":"partial"},{"evidence":"No canonical append-only record proves eligibility, one idempotency key, receiving-strategy acceptance, expiry, closure, and downstream ownership.","integration":"Idempotent lifecycle proposal and acceptance ledger","requiredBeforeActivation":true,"status":"missing"},{"evidence":"Suppression, reply memory, tasks, and contact history exist in fragments and are not yet enforced through one pre-proposal decision.","integration":"Global suppression, contact history, and owner capacity resolver","requiredBeforeActivation":true,"status":"partial"},{"evidence":"The existing lifecycle monitor can perform direct reminder behavior, but it is legacy, unbound to this canonical contract, and is not certified for dispatch.","integration":"Legacy lifecycle-monitor direct sender","requiredBeforeActivation":true,"status":"blocked"}],"learningInputs":["source entity and lifecycle event","trigger and delay","eligibility and suppression decision","idempotency key","proposed receiving strategy and version","destination and CTA snapshot","owner capacity","acceptance or rejection reason","downstream customer completion or accepted route","complaint, opt-out, duplicate, or trust signal"],"nurtureRules":["This controller performs no nurture and owns no message sequence.","A receiving strategy may accept only the proposed purpose and must apply its own approved cadence, permissions, and stop rules.","Repeated incomplete signals do not create repeated proposals while the same idempotency key or accountable owner remains open."],"objective":"Detect one valid unfinished, stale, or newly eligible next step and create a deduplicated internal ownership proposal for the exact responsible strategy without sending or publishing anything.","offer":"An internal eligibility, suppression, capacity, and ownership decision that produces an auditable task proposal or closes with a reason; the controller never presents an external offer.","primaryChannels":["operator_task"],"prioritizationRules":["Prioritize customer-requested unfinished actions and time-sensitive safety or document needs before optional cross-lane proposals.","Choose the existing accountable owner and exact approved destination over a higher-scoring but ambiguous next-best action.","Apply global and path-specific caps, owner capacity, evidence freshness, and expected incremental customer value before proposing a task."],"problem":"Disconnected lifecycle signals create stalled journeys, duplicate contact, generic nurture, conflicting owners, and messages whose purpose or destination cannot be justified.","reactivationRules":["A closed or suppressed proposal may be reconsidered only after a materially new authoritative event, permission restoration, destination repair, or owner-capacity change.","Long-dormant reactivation, a new purpose, or a financial, credit, or investment route always requires human review before receiving-strategy acceptance."],"secondaryChannels":["no_outreach"],"sourceData":["authoritative customer, profile, case, questionnaire, and DealVault lifecycle records","CRM tasks and owner capacity","reply memory and prior contact history","global and path-specific suppression state","receiving strategy version, destination, CTA, and cadence contract","legacy lifecycle-monitor observations without sender authority","future idempotent lifecycle proposals and acceptance events"],"sourceDataRequirements":[{"authority":"The originating VestBlock case, profile, questionnaire, credit, DealVault, or other governed record service","freshnessRule":"Re-read the authoritative record immediately before proposal creation and close the proposal if the state, owner, or completion evidence changes.","requiredEvidence":["entity namespace and ID","current lifecycle state or event","event time","customer owner","incomplete or newly eligible action","source strategy version when available"],"source":"authoritative customer lifecycle signal"},{"authority":"CRM communication permissions, suppression records, and reply memory","freshnessRule":"Recheck immediately before proposal creation and again by the receiving strategy before any later dispatch.","requiredEvidence":["purpose-specific channel permission","global suppression result","path-specific cap","last contact","last reply and disposition","complaint, bounce, or DNC state"],"source":"permission, contact, reply, and suppression context"},{"authority":"Target Gate 3C active strategy-version resolver and idempotent proposal ledger; not yet implemented","freshnessRule":"Resolve the active receiving version and capacity at proposal time; expire the proposal on any version, destination, owner, or evidence change.","requiredEvidence":["receiving strategy and active version","destination and CTA snapshot","eligible action","owner","capacity","acceptance or rejection event","idempotency key"],"source":"receiving strategy contract and owner capacity"}],"stopRules":["Stop on opt-out, complaint, hard bounce, DNC, withdrawal, or permission loss.","Stop on a reply that needs human handling, a verified conversion, successful handoff, disqualification, or identity conflict.","Stop on stale evidence, an invalid destination, a missing strategy or message version, duplicate ownership, capacity failure, or a kill switch.","Close immediately on completion, accepted route, suppression, exhausted path cap, stale evidence, inactive receiving version, or owner rejection.","Stop after any reply needing human handling and never automatically create a follow-up proposal from that reply.","Disable proposal generation when evidence shows the controller increases complaints, duplicates, or loss of trust."],"targetParticipant":"Existing VestBlock customers and participants with a registered profile, case, questionnaire, record, or other governed customer state that may warrant one relevant next action.","valueExchange":"The controller preserves continuity by proposing one evidence-backed next action to the correct owner while protecting the participant from duplicate, irrelevant, or unauthorized contact.","versionDecisionRule":{"autonomousMaterialChange":false,"promote":"Promote only after two complete 30-day windows each contain at least 50 eligible idempotent lifecycle proposals and 15 explicit receiving-strategy acceptances, with zero direct sends, duplicate proposals, suppression failures, or ownership conflicts.","requiredCompleteWindows":2,"retire":"Retire a trigger or route after a direct-send boundary breach, material trust or compliance failure, or two complete windows without receiving-strategy acceptance after adequate eligible exposure.","revise":"Revise trigger, eligibility, owner routing, or expiry logic when attributable rejection and downstream completion evidence identifies a bounded correctable issue."}},"crm_owner_key":"vestblock_crm","cta_label":null,"destination_mode":"internal_only","destination_path":null,"execution_mode":"internal_only","expected_current_version":1,"expected_prior_fingerprint":"77a0e59192c2ff424bd37b73c59ab20d","external_activation":"blocked","external_send_cap":0,"lifecycle_contract_json":{"cadence":["Evaluate once per new authoritative source event or freshness boundary.","Permit at most one open idempotent proposal per participant, source event, purpose, and receiving strategy.","Expire without contact when evidence, destination, version, permission, or owner capacity becomes stale."],"initialState":"triggered","persistedEvents":[],"persistedStates":[],"recordAuthority":"No canonical lifecycle-orchestration proposal authority exists. Workspace tasks, reply memory, source records, and the legacy lifecycle monitor are partial evidence and do not persist this governed controller lifecycle.","stateNotes":{"closed":"closed is target-only and is not currently persisted by a future idempotent lifecycle-proposal and receiving-strategy-acceptance ledger.","eligible":"eligible is target-only and is not currently persisted by a future idempotent lifecycle-proposal and receiving-strategy-acceptance ledger.","owner_assigned":"owner_assigned is target-only and is not currently persisted by a future idempotent lifecycle-proposal and receiving-strategy-acceptance ledger.","receiving_strategy_accepted":"receiving_strategy_accepted is target-only and is not currently persisted by a future idempotent lifecycle-proposal and receiving-strategy-acceptance ledger.","routed":"routed is target-only and is not currently persisted by a future idempotent lifecycle-proposal and receiving-strategy-acceptance ledger.","suppressed":"suppressed is target-only and is not currently persisted by a future idempotent lifecycle-proposal and receiving-strategy-acceptance ledger.","task_proposed":"task_proposed is target-only and is not currently persisted by a future idempotent lifecycle-proposal and receiving-strategy-acceptance ledger.","triggered":"triggered is target-only and is not currently persisted by a future idempotent lifecycle-proposal and receiving-strategy-acceptance ledger."},"states":["triggered","eligible","owner_assigned","task_proposed","receiving_strategy_accepted","routed","suppressed","closed"],"stopConditions":["routed","suppressed","closed","direct_send_attempted","identity_conflict","duplicate_proposal","receiving_version_inactive"],"targetOnlyStages":["triggered","eligible","owner_assigned","task_proposed","receiving_strategy_accepted","routed","suppressed","closed"],"terminalStates":["routed","suppressed","closed"],"transitions":[{"event":"lifecycle_signal_passes_initial_eligibility","from":"triggered","persistence":"target_only","to":"eligible"},{"event":"lifecycle_signal_fails_safety_or_permission_check","from":"triggered","persistence":"target_only","to":"suppressed"},{"event":"lifecycle_signal_is_stale_duplicate_or_completed","from":"triggered","persistence":"target_only","to":"closed"},{"event":"accountable_receiving_owner_resolved","from":"eligible","persistence":"target_only","to":"owner_assigned"},{"event":"eligible_signal_blocked_by_fresh_suppression","from":"eligible","persistence":"target_only","to":"suppressed"},{"event":"eligible_signal_loses_incremental_value","from":"eligible","persistence":"target_only","to":"closed"},{"event":"idempotent_owner_task_proposal_created","from":"owner_assigned","persistence":"target_only","to":"task_proposed"},{"event":"owner_capacity_or_destination_unavailable","from":"owner_assigned","persistence":"target_only","to":"closed"},{"event":"receiving_strategy_accepts_proposal_ownership","from":"task_proposed","persistence":"target_only","to":"receiving_strategy_accepted"},{"event":"proposal_invalidated_by_permission_or_suppression_change","from":"task_proposed","persistence":"target_only","to":"suppressed"},{"event":"proposal_rejected_expired_or_source_changed","from":"task_proposed","persistence":"target_only","to":"closed"},{"event":"accepted_proposal_handoff_recorded","from":"receiving_strategy_accepted","persistence":"target_only","to":"routed"},{"event":"accepted_proposal_invalidated_before_handoff","from":"receiving_strategy_accepted","persistence":"target_only","to":"closed"}]},"outcome_contract_json":{"attributionDimensions":["portfolio","operating strategy version","source entity and version","trigger","purpose","receiving strategy version","owner","proposal","acceptance","downstream outcome"],"businessValue":"Cleaner ownership and recoverable customer journeys without generic nurture; customer completion or route acceptance remains a separately verified downstream business outcome.","exposureUnit":"eligible_idempotent_lifecycle_proposals","leadingIndicators":["authoritative lifecycle signals","signals passing eligibility","suppression pass rate","owner resolution","idempotent task proposals","proposal response time","receiving-strategy rejection reasons","downstream customer completions"],"learningInputs":["operating strategy version","source entity and event","trigger","delay","eligibility result","suppression and contact context","idempotency key","receiving strategy and version","destination snapshot","acceptance or rejection","downstream outcome"],"learningWindowDays":30,"minimumExposure":50,"minimumPrimaryConversions":15,"observableCurrentOutcome":{"available":false,"evidence":"Workspace tasks, source records, reply memory, suppression fragments, and a lifecycle monitor exist, but none is the canonical governed proposal-and-acceptance authority.","limitation":"No canonical record currently proves an eligible idempotent lifecycle proposal and explicit receiving-strategy acceptance."},"primaryConversionEvent":"The selected receiving strategy explicitly accepts ownership of an eligible, idempotent lifecycle proposal.","requiredCompleteWindows":2,"safeguards":["Require two complete learning windows before recommending promotion.","Do not declare a winner from opens, clicks, or other vanity engagement alone.","A complaint, compliance failure, identity conflict, duplicate dispatch, or suppression breach blocks promotion.","Material audience, offer, cadence, claim, destination, or channel changes remain human-reviewed proposals.","Do not treat signal detection, eligibility, task creation, delivery, open, click, or a direct reminder as receiving-strategy acceptance.","Receiving-strategy acceptance is the controller outcome and must not be represented as customer completion, route acceptance, or business conversion."],"stopConditions":["direct send or n8n invocation","duplicate proposal","suppression or permission failure","stale source evidence","inactive receiving version","broken destination","owner conflict","trust or complaint regression"],"targetOutcomeObservable":false,"verifiedOutcomeRule":"Count once when a canonical idempotent proposal records current source evidence, suppression and permission checks, an exact active receiving strategy version, destination/CTA snapshot, accountable owner, and that strategy's explicit acceptance event."},"owner_contract_json":{"automationRole":"vestblock_application","crmAuthority":"vestblock_crm","dispatchAuthority":"none_in_gate_3b","handoffRules":["The controller transfers one exact proposal only after the receiving strategy explicitly accepts its current version and ownership.","The receiving strategy alone owns any message, cadence, destination, dispatch, reply, and customer outcome; this controller never regains sender authority."],"humanOwner":"A VestBlock operator owns ambiguous identity, dormant reactivation, purpose changes, sensitive cross-lane routes, owner conflicts, and rejected proposals.","recordOwner":"CRM must own future eligibility, suppression, idempotency, owner routing, proposal, acceptance, expiry, and closure records; current sources remain owned by their originating service."},"required_current_status":"draft","source_provenance_json":[{"kind":"gate_3a_registry_seed","observedAt":"2026-08-15","source":"Gate 3A canonical governed registry"},{"kind":"founder_approved_architecture","observedAt":"2026-08-15","source":"Gate 2 canonical strategy registry"},{"kind":"repository_consumer_audit","observedAt":"2026-08-15","source":"workspace task, reply-memory, suppression, lifecycle-monitor, and receiving-strategy ownership consumer audit"}],"strategy_key":"customer_lifecycle_orchestration"},{"activation_blockers":["Version 1 remains draft and has no founder-approved activation event.","External send capacity is zero and no live-send approval exists.","Gate 3C canonical consumer binding is not implemented.","The public demo request and authenticated product records are not joined into one attributable activation lifecycle.","A verified first record cannot yet prove that an invited or otherwise authorized participant accepted access."],"automation_owner_key":"vestblock_application","contract_json":{"activationReadiness":{"blockers":["Canonical strategy-version binding is absent.","Demo requests do not join to product activation.","Authorized-participant acceptance is not a governed outcome.","External onboarding sends are unapproved."],"readyElements":["The private demo destination exists.","Authenticated DealVault records and audit evidence exist.","Public demo interest can be recorded."],"status":"blocked"},"cadenceSteps":[{"channels":["website_notification"],"condition":"A valid demo request was recorded.","purpose":"Confirm receipt without implying activation.","timing":"immediate"},{"channels":["operator_task"],"condition":"The request is complete, unsuppressed, and owned.","purpose":"Qualify the use case, access boundary, and next product step.","timing":"within one business day"},{"channels":["website_notification","resend_email","outlook_graph"],"condition":"The participant requested follow-up, the same gap remains, and no stop condition applies.","purpose":"Resolve one verified missing activation step.","timing":"days 1, 3, 7, and 14 after an approved onboarding start"}],"channelSelectionRules":["Use /dealvault/demo for the public request and the authenticated application for records and access decisions.","Use email only for the requested demo or transactional product step after validating the address and purpose-specific permission.","Use an operator task for qualification, restricted opportunity access, participant authorization, or sensitive-record review."],"complianceLimits":["Do not guarantee funding, approval, credit-score change, deletion, income, investment return, property availability, government award, deal outcome, or transaction timing.","Keep analysis, matching, marketing, provider sharing, public display, and outreach permissions separate and purpose-specific.","Recheck global suppression, DNC, withdrawal, complaint, hard bounce, identity conflict, and destination health immediately before any later dispatch.","A DealVault record documents submitted evidence and activity; it does not itself establish legal enforceability, ownership, availability, performance, closing, or return.","Store and expose only the minimum information authorized for each participant and purpose."],"crossLaneRoutes":[{"handoff":"Offer a permissioned Capital intake without sharing DealVault records automatically.","requiresReceivingStrategyAcceptance":true,"to":"capital_readiness_intake","trigger":"A participant-owned record reveals a separately requested capital-readiness need."},{"handoff":"Create an operator-reviewed service request containing only approved facts.","requiresReceivingStrategyAcceptance":true,"to":"service_provider_network","trigger":"A milestone or record owner requests an appropriate service-provider introduction."},{"handoff":"Propose an internal lifecycle task that DealVault must accept before any communication.","requiresReceivingStrategyAcceptance":true,"to":"customer_lifecycle_orchestration","trigger":"A documented activation step becomes stale without authorizing a message."}],"disqualificationCriteria":["Fabricated identity, unverifiable use case, prohibited content, or unresolved access conflict.","A request to imply that a record proves legal enforceability, asset ownership, deal availability, performance, closing, or return beyond verified facts.","Sensitive third-party information without authority to store, share, or invite access."],"eligibilityCriteria":["A demo request identifies a real participant, organization or team context, reachable contact, and plausible coordination use case.","Authenticated product use is tied to permitted deal or opportunity data, role-based access, and an accepted diligence boundary.","Records, proofs, participants, milestones, and payout references have attributable owners and source evidence."],"failureConditions":["Broken access control","Unowned or sensitive record","Demo-to-account attribution gap","Unauthorized participant access","Misleading proof or outcome representation","Product health failure"],"followupCadence":["Immediate on-page acknowledgement of a valid demo request.","Operator qualification review within one business day.","If separately permitted, guidance at days 1, 3, 7, and 14 only for the next documented activation gap, then stop."],"handoffRules":["The demo-request lead records interest only; it does not own authenticated product state or prove activation.","The DealVault application owns records; an operator owns qualification and restricted access; a receiving lane must accept any cross-lane request."],"humanApprovalPoints":["Demo qualification","Restricted opportunity access","Third-party participant invitation","Sensitive documents or proofs","Financial, return, compensation, or legal-enforceability language"],"integrationDependencies":[{"evidence":"Application consumers do not yet persist or resolve canonical operating-strategy version IDs.","integration":"canonical strategy-version binding","requiredBeforeActivation":true,"status":"gate_3c"},{"evidence":"Deal, proof, status-event, payout, milestone, audit, and usage records exist.","integration":"DealVault 