uiredCompleteWindows":2,"safeguards":["Require two complete learning windows before recommending promotion.","Do not declare a winner from opens, clicks, or other vanity engagement alone.","A complaint, compliance failure, identity conflict, duplicate dispatch, or suppression breach blocks promotion.","Material audience, offer, cadence, claim, destination, or channel changes remain human-reviewed proposals.","Measure demo request, demo completion, account creation, first record, participant acceptance, activation, and retention as separate events."],"stopConditions":["access-control failure","misleading record claim","sensitive data without authority","product health failure","no qualified activation after two windows"],"targetOutcomeObservable":false,"verifiedOutcomeRule":"Count once when a qualified demo request is linked to an authenticated pilot account, its first verified record, and an authorized participant acceptance event."},"owner_contract_json":{"automationRole":"vestblock_application","crmAuthority":"vestblock_crm","dispatchAuthority":"none_in_gate_3b","handoffRules":["A demo request is not an activated account.","No cross-lane strategy receives record data without purpose-specific permission and explicit acceptance."],"humanOwner":"A VestBlock operator owns qualification, restricted access, participant authorization, and sensitive-record review.","recordOwner":"The CRM owns demo interest; the DealVault application owns authenticated records and audit facts."},"required_current_status":"draft","source_provenance_json":[{"kind":"gate_3a_registry_seed","observedAt":"2026-08-15","source":"Gate 3A canonical governed registry"},{"kind":"founder_approved_architecture","observedAt":"2026-08-15","source":"Gate 2 canonical strategy registry"},{"kind":"repository_consumer_audit","observedAt":"2026-08-15","source":"DealVault demo-request, authenticated application, and record-authority audit"}],"strategy_key":"dealvault_activation"},{"activation_blockers":["Version 1 remains draft and has no founder-approved activation event.","External send capacity is zero and no live-send approval exists.","Gate 3C canonical consumer binding is not implemented.","The current investor route captures a real-estate acquisition profile only; it does not support the broader cross-sector capital-relationship identity previously described.","No governed investor-relationship review, opportunity review, bilateral introduction, diligence, or verified-value lifecycle is currently persisted.","Historical investor automation ran without a real sourced participant-profile contract and is not an approved source or executor.","Investment, securities, return, suitability, offering, compensation, and opportunity language requires operator review."],"automation_owner_key":"vestblock_application","contract_json":{"activationReadiness":{"blockers":["Canonical strategy-version binding is absent.","The shared investor form cannot support the prior cross-sector capital-partner scope.","Relationship and opportunity acceptance events are missing.","Verified diligence/value attribution is absent.","External sends and introductions are unapproved."],"readyElements":["The current real-estate investor profile route exists.","The contract separates investor-profile intake from buyer-strategy property sourcing.","The historical empty automation loop is explicitly excluded."],"status":"blocked"},"cadenceSteps":[{"channels":["website_notification","resend_email"],"condition":"The participant profile is active and separately permitted for profile notifications.","purpose":"Reconfirm capacity, structure, criteria, conflicts, and permissions.","timing":"every 30 to 60 days while active"},{"channels":["operator_task"],"condition":"A current authorized opportunity may fit a verified profile.","purpose":"Review fit, authority, legal boundaries, permitted facts, and compensation.","timing":"before any opportunity disclosure"},{"channels":["website_notification","resend_email","o