ion","trigger":"The participant wants VestBlock to source properties against a current buy box."},{"handoff":"Route the sponsor to Capital without representing investor interest or sharing this profile automatically.","requiresReceivingStrategyAcceptance":true,"to":"capital_readiness_intake","trigger":"A separately permissioned sponsor or project needs capital-readiness review."},{"handoff":"Offer an access-controlled DealVault review after record authority is established.","requiresReceivingStrategyAcceptance":true,"to":"dealvault_activation","trigger":"Both parties accept a relationship that needs controlled records and diligence continuity."}],"disqualificationCriteria":["Identity, entity, capacity, proof, permission, or ownership conflict.","A request for unreviewed solicitation, return guarantee, suitability determination, concealed compensation, or unsupported opportunity availability.","Stale criteria, regulatory concern, withdrawn permission, or a property-only buy box that belongs in buyer activation."],"eligibilityCriteria":["An active participant profile exists for role=investor with verified identity or entity.","Target markets, property types, acquisition strategy, budget or capacity path, and current verification are documented within the current real-estate profile.","Matching and channel permissions are explicit; any securities, offering, suitability, or compensation boundary is identified for operator review."],"failureConditions":["Unverified identity or capacity","Stale criteria","Regulatory or offering concern","Permission withdrawal","Unreviewed opportunity disclosure","Empty-source automation"],"followupCadence":["Reconfirm high-volatility capacity and criteria every 30 days; complete a full relationship review no later than 60 days.","For an operator-approved introduction, use only the approved opportunity-specific cadence and stop on either party response.","No cadence may use the empty historical automation loop."],"handoffRules":["Professional participant activation owns every pre-active state and completion reminder.","This strategy owns only an accepted active investor profile, relationship review, and operator-approved introduction; the receiving opportunity owner must also accept."],"humanApprovalPoints":["Role/entity/capacity verification","Every opportunity disclosure","Every introduction","Investment/securities/return/suitability language","Compensation and conflicts","Diligence or verified-value conclusion"],"integrationDependencies":[{"evidence":"Application consumers do not yet persist or resolve canonical operating-strategy version IDs.","integration":"canonical strategy-version binding","requiredBeforeActivation":true,"status":"gate_3c"},{"evidence":"The role=investor route exists and reuses real-estate buyer fields; it can capture a real-estate acquisition thesis but cannot represent a broader cross-sector capital partner.","integration":"Real-estate investor participant profile","requiredBeforeActivation":true,"status":"partial"},{"evidence":"No governed record currently persists relationship review, opportunity review, bilateral acceptance, diligence, and verified value.","integration":"Investor relationship and opportunity match authority","requiredBeforeActivation":true,"status":"missing"},{"evidence":"Historical runs exist without a sourced current profile contract and must remain disabled rather than become an executor.","integration":"Historical investor automation","requiredBeforeActivation":false,"status":"blocked"}],"learningInputs":["participant segment","sector","geography","structure","capacity","opportunity fit","decline reason","operator decision","bilateral acceptance","diligence stage","verified outcome"],"nurtureRules":["Nurture only criteria freshness, participant-requested education, or a specific approved relationship gap.","Do not imply access to inventory, investment suitability, returns, capital availability, or transaction timing."],"objective":"Capture a current 