ia":["The participant supplies the required questionnaire fields.","Analysis consent is explicit.","Any marketing or progress follow-up permission is separately recorded."],"failureConditions":["Missing analysis consent","Roadmap generation failure","Broken destination","Unbounded AI claim","Optional contact without marketing/follow-up permission"],"followupCadence":["Immediate roadmap generation and display.","Optional checkpoints at days 7, 30, 60, and 90.","No optional reminder without separate permission."],"handoffRules":["Roadmap owns educational sequencing only.","The receiving strategy rechecks eligibility, permissions, destination, communication, and outcome ownership."],"humanApprovalPoints":["Financial, credit, legal, tax, investment, or underwriting interpretation","Material AI recommendation change","Requested operator follow-up","Cross-lane offer outside the stated purpose"],"integrationDependencies":[{"evidence":"Application consumers do not yet persist or resolve canonical operating-strategy version IDs.","integration":"canonical strategy-version binding","requiredBeforeActivation":true,"status":"gate_3c"},{"evidence":"next_move_questionnaires stores the submitted snapshot and roadmap JSON.","integration":"Next Move persistence","requiredBeforeActivation":true,"status":"available"},{"evidence":"No generic questionnaire status or canonical action-progress event model exists.","integration":"Roadmap action-progress lifecycle","requiredBeforeActivation":true,"status":"missing"}],"learningInputs":["abandonment step","focus/path","roadmap model","saved action","usefulness feedback","cross-lane transition","customer-reported progress"],"nurtureRules":["Nurture follows the saved roadmap and never introduces an unrelated offer.","Each receiving lane owns its own qualification after an explicit handoff."],"objective":"Generate and save a practical educational sequence across credit, funding, income, business readiness, property, and opportunity paths.","offer