:"missing"}],"learningInputs":["partner type","capability fit","terms","disclosure","test-referral acceptance","completion","quality","complaint","attributed economics","repeat fit"],"nurtureRules":["No external nurture is authorized.","A future sequence must reference a verified capability fit and disclosed relationship purpose, never generic partnership language."],"objective":"Establish transparent, permissioned partner relationships and evaluate service quality through disclosed, operator-approved test referrals.","offer":"A future governed partner application and operator-approved test-referral path; no public application or live referral promise exists in Gate 3B.","primaryChannels":["operator_task","no_outreach"],"prioritizationRules":["No partner is prioritized for outreach until the destination and partner record are approved.","Future review prioritizes verified customer fit, quality, disclosure completeness, capacity, and accountable ownership.","Economics never override customer fit, consent, compliance, or quality evidence."],"problem":"Scattered links and legacy affiliate mechanics can create duplicate ownership, undisclosed economics, unclear customer consent, and unmeasured quality.","reactivationRules":["There is no inactive external sequence to reactivate.","A future paused partner requires corrected terms, quality, complaint, conflict, or permission evidence and operator approval."],"secondaryChannels":["no_outreach"],"sourceData":["future governed partner profiles","future partner terms and disclosure records","future test-referral and quality outcomes","operator-supplied prospective partner evidence"],"sourceDataRequirements":[{"authority":"Future governed partner profile with operator attestation","freshnessRule":"Reverify identity, capacity, terms, disclosures, conflicts, and permissions before invitation and each test referral.","requiredEvidence":["legal identity","accountable contact","capabilities","geography","service evidence","conflicts","permissions"],"source":"Prospective partner evidence"},{"authority":"Future partner referral and quality ledger","freshnessRule":"Bind each referral to the terms and permissions current at the time of operator approval.","requiredEvidence":["customer permission","fit decision","disclosures","terms version","bilateral acceptance","completion","quality","attributed economics"],"source":"Test-referral evidence"}],"stopRules":["Stop on opt-out, complaint, hard bounce, DNC, withdrawal, or permission loss.","Stop on a reply that needs human handling, a verified conversion, successful handoff, disqualification, or identity conflict.","Stop on stale evidence, an invalid destination, a missing strategy or message version, duplicate ownership, capacity failure, or a kill switch.","Pause or end on undisclosed compensation, conflict, poor verified service, complaint, regulatory uncertainty, nonperformance, or attribution dispute."],"targetParticipant":"Verified organizations and professionals with complementary capabilities and a documented customer or ecosystem fit.","valueExchange":"A prospective partner provides verifiable capabilities, service evidence, conflicts, terms, and permissions in exchange for a governed test-referral review.","versionDecisionRule":{"autonomousMaterialChange":false,"promote":"Promote only after two complete 90-day windows each include ten operator-approved test-referral offers and five accepted referrals with complete disclosures and no quality or complaint regression.","requiredCompleteWindows":2,"retire":"Retire a relationship after material disclosure or regulatory failure, unresolved complaint, poor verified service, or two reviewed windows without accepted referrals.","revise":"Revise one partner segment or term when attributable fit, response, disclosure, or quality evidence identifies a correctable problem."}},"crm_owner_key":"vestblock_crm","cta_label":null,"destination_mode":"unresolved","destination_path":null,"execution_mode":"inactiv