ck_crm","dispatchAuthority":"none_in_gate_3b","handoffRules":["At active, emit one idempotent handoff to the selected role strategy and require that strategy to accept ownership.","After accepted handoff, this strategy permanently relinquishes completion reminders, criteria freshness, matching, opportunity communication, and outcome ownership."],"humanOwner":"A VestBlock operator owns identity, role, verification, public-field, conflict, and activation decisions.","recordOwner":"Participant profile service exclusively owns the pre-active profile, status, identity, criteria, permissions, and verification provenance."},"required_current_status":"draft","source_provenance_json":[{"kind":"gate_3a_registry_seed","observedAt":"2026-08-15","source":"Gate 3A canonical governed registry"},{"kind":"founder_approved_architecture","observedAt":"2026-08-15","source":"Gate 2 canonical strategy registry"},{"kind":"repository_consumer_audit","observedAt":"2026-08-15","source":"participant profile statuses, operator verification, consent fields, and role-handoff consumer audit"}],"strategy_key":"professional_participant_activation"},{"activation_blockers":["Version 1 remains draft and has no founder-approved activation event.","External send capacity is zero and no live-send approval exists.","Gate 3C canonical consumer binding is not implemented.","Primary outcome is not currently observable as one accepted case-or-match review across the fragmented source, market-state, run, and lead records.","DealMachine API access is unavailable until a new key is supplied and must not be replaced with export automation."],"automation_owner_key":"vestblock_application","contract_json":{"activationReadiness":{"blockers":["No single persisted discovery lifecycle exists.","Primary outcome is not currently observable as one accepted case-or-match review.","Canonical strategy-version binding is absent.","Source-owner conflicts and DealMachine access remain unresolved."],"readyElements":["Internal source and market-state records exist.","Canonical source-tactic crosswalks exist.","This contract prohibits direct outreach."],"status":"blocked"},"cadenceSteps":[{"channels":["no_outreach"],"condition":"Provider access, terms, budget, and source health are current.","purpose":"Refresh approved source evidence and expire stale facts.","timing":"daily where permitted"},{"channels":["operator_task"],"condition":"The candidate has complete source evidence.","purpose":"Review provenance, suppression, sensitivity, and demand fit.","timing":"after normalization and dedupe"}],"channelSelectionRules":["Create an operator task for evidence review.","No source adapter, source cron, or tactic may select an external channel.","Any later seller communication inherits the seller strategy contract after an accepted handoff."],"complianceLimits":["Do not guarantee funding, approval, credit-score change, deletion, income, investment return, property availability, government award, deal outcome, or transaction timing.","Keep analysis, matching, marketing, provider sharing, public display, and outreach permissions separate and purpose-specific.","Recheck global suppression, DNC, withdrawal, complaint, hard bounce, identity conflict, and destination health immediately before any later dispatch.","Public records do not establish motivation or blanket permission to contact.","Respect provider licensing, field-use, storage, and freshness terms."],"crossLaneRoutes":[{"handoff":"Create or link a seller-case candidate without authorizing dispatch.","requiresReceivingStrategyAcceptance":true,"to":"seller_options_intake","trigger":"An operator accepts a provenance-backed candidate for a customer-safe seller review."},{"handoff":"Create a blinded operator match review; do not represent availability.","requiresReceivingStrategyAcceptance":true,"to":"buyer_buy_box_activation","trigger":"A verified property fact set matches a current active buy box."},{"handoff":"Request DealVault review only after opportunity authority and access are established.","requiresReceivingStrategyAcceptance":true,"to":"dealvault_activation","trigger":"An operator-approved opportunity needs controlled records."}],"disqualificationCriteria":["Unresolved property identity or duplicate.","Stale, unsupported, prohibited, or license-incompatible source evidence.","Protected-class targeting, unsupported distress inference, or missing contact provenance."],"eligibilityCriteria":["Property identity and source event are present.","Observed timestamp, freshness rule, dedupe key, and provenance are recorded.","Owner/contact provenance and suppression or lawful-basis review can be completed before any handoff."],"failureConditions":["Systemic provenance failure","Repeated stale or duplicate data","Provider contract or budget failure","High suppression or complaint signal","No accepted review across two windows"],"followupCadence":["Daily internal source refresh where permitted.","Operator review based on freshness and demand fit.","No external cadence; seller or buyer strategies own any accepted handoff."],"handoffRules":["Discovery owns evidence and qualification only.","The seller or buyer strategy must accept the candidate and owns every later customer interaction."],"humanApprovalPoints":["Natural-person contact eligibility","Sensitive or protected context","Source reactivation","Seller-case or buyer-match acceptance","Property availability or value language"],"integrationDependencies":[{"evidence":"Application consumers do not yet persist or resolve canonical operating-strategy version IDs.","integration":"canonical strategy-version binding","requiredBeforeActivation":true,"status":"gate_3c"},{"evidence":"Source events, market state, runs, and leads exist without one canonical discovery lifecycle.","integration":"Source event and market-state services","requiredBeforeActivation":true,"status":"partial"},{"evidence":"ATTOM enrichment exists but remains subject to freshness, terms, and operator review.","integration":"ATTOM","requiredBeforeActivation":false,"status":"available"},{"evidence":"The current API key is unavailable; future contact data must come from the new API, not export automation.","integration":"DealMachine native API","requiredBeforeActivation":false,"status":"blocked"}],"learningInputs":["provider/source","jurisdiction","freshness","source tactic","dedupe result","review reason","contact quality","accepted case or match"],"nurtureRules":["This internal strategy does not nurture people.","A held candidate may receive a scheduled evidence refresh, not a communication sequence."],"objective":"Identify provenance-backed property signals for operator review without claiming that a property is available or an owner is motivated.","offer":"An internal evidence-prioritization and operator-review queue with no direct customer CTA or dispatch.","primaryChannels":["operator_task","no_outreach"],"prioritizationRules":["Prioritize current multi-source corroboration and explicit buyer-demand fit.","Route sensitive contexts to operator review without scoring them as motivation.","Lower priority or reject sources with repeated staleness, suppression, or identity failure."],"problem":"Raw property signals are noisy, age quickly, and create duplicate or inappropriate contact when provenance and ownership are fragmented.","reactivationRules":["Re-open a held or rejected candidate only on a new, timestamped material source event.","A source disabled for systemic failure requires operator approval and a passed provenance test before reuse."],"secondaryChannels":["no_outreach"],"sourceData":["strategy_source_events","strategy_market_state","command_center_strategy_runs","legacy leads","ATTOM","permitted HomeHarvest history","future native DealMachine API"],"sourceDataRequirements":[{"authority":"Application source orchestrator","freshnessRule":"Use the provider-specific SLA; a historical export is never current evidence.","requiredEvidence":["source names