d/no-bid approval.","requiredEvidence":["identity/entity","registrations","certifications","capabilities","capacity","conflicts","document state","permission"],"source":"Participant readiness evidence"}],"stopRules":["Stop on opt-out, complaint, hard bounce, DNC, withdrawal, or permission loss.","Stop on a reply that needs human handling, a verified conversion, successful handoff, disqualification, or identity conflict.","Stop on stale evidence, an invalid destination, a missing strategy or message version, duplicate ownership, capacity failure, or a kill switch.","Stop on expiration, cancellation, entity ineligibility, conflict, missing registration, insufficient capacity, unsupported claim, source discrepancy, or operator no-bid."],"targetParticipant":"Qualified small businesses and partners with verifiable capabilities, registrations, certifications, capacity, and interest in relevant public-sector work.","valueExchange":"Official sources and participant-submitted facts support a cited internal fit review; a future qualified participant receives a bounded readiness or bid/no-bid plan, never an award promise.","versionDecisionRule":{"autonomousMaterialChange":false,"promote":"Promote only after two complete 30-day windows each include 30 current fit-screened official opportunities and five participant-accepted operator-reviewed readiness or bid/no-bid plans, with no source or claim regression.","requiredCompleteWindows":2,"retire":"Retire a source or segment after material source discrepancy, prohibited claim, or two reviewed windows without accepted readiness progression.","revise":"Revise a source, fit rule, or readiness requirement when attributable no-fit, deadline, or source evidence identifies a correctable issue."}},"crm_owner_key":"vestblock_crm","cta_label":null,"destination_mode":"internal_only","destination_path":null,"execution_mode":"internal_only","expected_current_version":1,"expected_prior_fingerprint":"a6429114c850a326b50d68c07766daa2","external_a