    contract_json JSONB,
    lifecycle_contract_json JSONB,
    owner_contract_json JSONB,
    outcome_contract_json JSONB,
    source_provenance_json JSONB,
    crm_owner_key TEXT,
    automation_owner_key TEXT,
    external_send_cap INTEGER,
    external_activation TEXT,
    activation_blockers JSONB
  )
)
UPDATE public.operating_strategy_versions version
SET
  execution_mode = manifest.execution_mode,
  destination_mode = manifest.destination_mode,
  destination_path = manifest.destination_path,
  cta_label = manifest.cta_label,
  contract_json = manifest.contract_json,
  lifecycle_contract_json = manifest.lifecycle_contract_json,
  owner_contract_json = manifest.owner_contract_json,
  outcome_contract_json = manifest.outcome_contract_json,
  source_provenance_json = manifest.source_provenance_json,
  crm_owner_key = manifest.crm_owner_key,
  automation_owner_key = manifest.automation_owner_key,
  external_send_cap = manifest.external_send_cap
FROM gate3b_manifest manifest
JOIN public.operating_strategies strategy
  ON strategy.strategy_key = manifest.strategy_key
WHERE version.operating_strategy_id = strategy.id
  AND version.version = manifest.expected_current_version
  AND version.status = manifest.required_current_status
  AND version.version = 1
  AND version.status = 'draft'
  AND version.external_send_cap = 0
  AND manifest.external_activation = 'blocked'
  AND manifest.external_send_cap = 0;

DO $gate3b_postconditions$
DECLARE
  expected_strategy_keys CONSTANT TEXT[] := ARRAY['business_acquisition_network', 'business_formation_readiness', 'buyer_buy_box_activation', 'capital_readiness_intake', 'content_authority_intelligence', 'credit_education_support', 'customer_lifecycle_orchestration', 'dealvault_activation', 'investor_capital_relationships', 'lender_provider_criteria', 'next_move_free_roadmap', 'partner_referral_network', 'professional_participant_activation', 'property_opportunity_discovery', 'public_sector_opportunity_readiness', 'seller_options_intake', 'service_provider_network']::TEXT[];
BEGIN
  IF (
    SELECT count(*)
    FROM public.operating_strategies strategy
    JOIN public.operating_strategy_versions version
      ON version.operating_strategy_id = strategy.id
    WHERE strategy.strategy_key = ANY(expected_strategy_keys)
      AND version.version = 1
      AND version.status = 'draft'
      AND version.external_send_cap = 0
      AND version.owner_contract_json ->> 'dispatchAuthority' = 'none_in_gate_3b'
  ) <> 17 THEN
    RAISE EXCEPTION 'Gate 3B did not update exactly 17 untouched version-1 drafts';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.operating_strategies strategy
    JOIN public.operating_strategy_versions version
      ON version.operating_strategy_id = strategy.id
    WHERE strategy.strategy_key = ANY(expected_strategy_keys)
      AND (
        version.status <> 'draft'
        OR version.external_send_cap <> 0
        OR version.approved_by_user_id IS NOT NULL
        OR version.approved_at IS NOT NULL
        OR version.activated_at IS NOT NULL
        OR version.retired_at IS NOT NULL
      )
  ) THEN
    RAISE EXCEPTION 'Gate 3B must leave all 17 contracts unapproved, inactive, and zero-send';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.operating_strategy_versions
    WHERE status = 'active'
       OR external_send_cap <> 0
       OR execution_mode IN ('internal_test', 'approved_live')
  ) THEN
    RAISE EXCEPTION 'Gate 3B must not activate any operating strategy or sending';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.orchestration_controls
    WHERE integration_key = 'n8n'
      AND live_send_enabled
  ) THEN
    RAISE EXCEPTION 'Gate 3B requires n8n live sending to remain disabled';
  END IF;
END
$gate3b_postconditions$;

DO $gate3b_postconditions$
DECLARE
  reviewable_count INTEGER;
  public_count INTEGER;
  internal_count INTEGER;
  unresolved_count INTEGER;
  lifecycle_count INTEGER;
  indicator_count INTEGER;
BEGIN
  SELECT COUNT(*)::INTEGER
    INTO reviewable_count
  FROM public.operating_strategy_versions strategy_version
  WHERE private.gate3b_valid_review_contract(strategy_version);

  IF reviewable_count <> 17 THEN
    RAISE EXCEPTION 'Gate 3B expected 17 complete reviewable draft contracts, found %.', reviewable_count;
  END IF;

  SELECT
    COUNT(*) FILTER (WHERE destination_mode = 'public_route')::INTEGER,
    COUNT(*) FILTER (WHERE destination_mode = 'internal_only')::INTEGER,
    COUNT(*) FILTER (WHERE destination_mode = 'unresolved')::INTEGER,
    COUNT(DISTINCT lifecycle_contract_json)::INTEGER,
    COUNT(DISTINCT outcome_contract_json -> 'leadingIndicators')::INTEGER
  INTO public_count, internal_count, unresolved_count, lifecycle_count, indicator_count
  FROM public.operating_strategy_versions
  WHERE version = 1;

  IF public_count <> 12 OR internal_count <> 3 OR unresolved_count <> 2 THEN
    RAISE EXCEPTION 'Gate 3B destination counts must be 12 public, 3 internal, and 2 unresolved.';
  END IF;
  IF lifecycle_count <> 17 OR indicator_count <> 17 THEN
    RAISE EXCEPTION 'Gate 3B contracts must have 17 lane-specific lifecycles and indicator sets.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.operating_strategy_versions version
    WHERE version.status <> 'draft'
      OR version.approved_by_user_id IS NOT NULL
      OR version.approved_at IS NOT NULL
      OR version.activated_at IS NOT NULL
      OR version.retired_at IS NOT NULL
      OR version.external_send_cap <> 0
      OR version.execution_mode IN ('internal_test', 'approved_live')
      OR private.gate3b_activation_ready(version.contract_json)
  ) THEN
    RAISE EXCEPTION 'Gate 3B must leave every operating version draft, unapproved, unactivated, zero-send, and activation-blocked.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.operating_strategy_version_events event
    WHERE event.event_type IN ('approved', 'activated', 'retired')
  ) THEN
    RAISE EXCEPTION 'Gate 3B did not authorize approval, activation, or retirement events.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.orchestration_controls
    WHERE integration_key = 'n8n'
      AND live_send_enabled
  ) THEN
    RAISE EXCEPTION 'Gate 3B requires n8n live sending to remain disabled.';
  END IF;
END;
$gate3b_postconditions$;
